// The product catalogue for hand declaration (S-INV-2). Two sources, merged into one list:
// 1) EVERY vendor/product pair that ever appeared in CISA KEV (content/catalog/kev-products.json, generated by `pnpm fixtures`; the Go backend embeds the same file); each pair can be chosen,
//    the match key is exactly the lower-case `vendor|product` of KEV so an alert matches exactly. Source: https://www.cisa.gov/known-exploited-vulnerabilities-catalog (CC0).
// 2) A curated list: products small businesses in Vietnam commonly use, called by commercial name. Each entry points at the real KEV key (kevMatch) if KEV has one,
//    otherwise a CPE-style `vendor|product` key (no exploited flaw yet, but one will match when it appears). The real version: generated from feeds/cpe-dict (DATA_PIPELINE §3).
// Stable ids: a curated entry has a fixed id; a KEV entry has the id `kev:<vendor>:<product>` (a slug).
import kevProducts from '../../../../content/catalog/kev-products.json'
import curatedData from '../../../../content/catalog/curated.json'
import type { AssetKind } from '@/lib/types'

export interface CatalogEntry {
  id: string; display: string; category: string; hint: string; vendor: string; product: string; kind: AssetKind
  kev: string[]; aliases: string[]; version_hint: string; kev_count: number; curated: boolean; order: number
}

interface KevRow { vendor: string; product: string; kev_count: number; last_added: string; ransomware: boolean }
const KEV = kevProducts as KevRow[]
const kevKey = (r: { vendor: string; product: string }) => `${r.vendor}|${r.product}`.toLowerCase()
const kevCountOf = new Map(KEV.map((r) => [kevKey(r), r.kev_count]))

/** Strip diacritics, lower-case, turn every odd character into a space: "Tường lửa FortiGate-60F" → "tuong lua fortigate 60f". */
export const fold = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/[^a-z0-9]+/g, ' ').trim()
const slug = (s: string) => fold(s).replace(/ /g, '-')

const OTHER = 'Other'

type K = AssetKind
/** content/catalog/curated.json: ONE data source for the web and the Go backend (modules/inventory embeds the same file). Array order = popularity. */
interface CuratedRow { display: string; category: string; kind: K; vendor: string; product: string; aliases: string; version_hint: string; kev_match?: string[] }
const CURATED = curatedData as CuratedRow[]

// A kev_match fragment "vendor|product" names exploited-list products by whole words, never by a piece of a word or by a list name
// that names another product. Written the same in core/productid/fragment.go (read its comment); search-golden.json proves they agree.
const QUALIFIERS = new Set(['software', 'appliance', 'appliances', 'device', 'devices', 'server', 'servers', 'series', 'router', 'routers', 'firmware', 'edition', 'editions', 'community', 'enterprise', 'data', 'center', 'web', 'ui', 'ce', 'ee'])
const fragmentWords = (s: string) => s.toLowerCase().replace(/[\u00a0\u202f]/g, ' ').replace(/\([^)]*\)/g, ' ').match(/[a-z0-9]+/g) ?? []
function fragWords(s: string): [string[], boolean] {
  const t = s.trim()
  return [fragmentWords(t.endsWith('*') ? t.slice(0, -1) : t), t.endsWith('*')]
}
const familyWord = (word: string, family: string) => word.startsWith(family) && (word.length === family.length || /[0-9]/.test(word[family.length]!))
function namesPart(part: string[], frag: string[], star: boolean): boolean {
  const n = frag.length
  if (part.length < n) return false
  for (let i = 0; i < n - 1; i++) if (part[i] !== frag[i]) return false
  if (star) return familyWord(part[n - 1]!, frag[n - 1]!)
  return part[n - 1] === frag[n - 1] && part.slice(n).every((w) => QUALIFIERS.has(w))
}
function fragmentMatch(fragment: string, vendor: string, product: string): boolean {
  const cut = fragment.indexOf('|')
  const [fv, fp] = cut < 0 ? [fragment, ''] : [fragment.slice(0, cut), fragment.slice(cut + 1)]
  const [v] = fragWords(fv)
  if (v.length) {
    const have = fragmentWords(vendor)
    let found = false
    for (let i = 0; i + v.length <= have.length && !found; i++) found = v.every((w, j) => have[i + j] === w)
    if (!found) return false
  }
  const [p, star] = fragWords(fp)
  if (!p.length) return true
  const name = product.toLowerCase().replace(/[\u00a0\u202f]/g, ' ').replace(/\([^)]*\)/g, ' ')
  if (namesPart(name.match(/[a-z0-9]+/g) ?? [], p, star)) return true
  return name.split(/\s*(?:,|\/|&|\band\b)\s*/).some((part) => namesPart(part.match(/[a-z0-9]+/g) ?? [], p, star))
}

export { fragmentMatch }

function kevKeysFor(matches: string[] | undefined, fallback: string): string[] {
  if (!matches?.length) return [fallback]
  const keys = new Set<string>()
  for (const m of matches) for (const r of KEV) if (fragmentMatch(m, r.vendor, r.product)) keys.add(kevKey(r))
  return keys.size ? [...keys] : [fallback]
}
const sumKev = (keys: string[]) => keys.reduce((n, k) => n + (kevCountOf.get(k) ?? 0), 0)

const curated: CatalogEntry[] = CURATED.map(({ display, category, kind, vendor, product, aliases, version_hint, kev_match }, i) => {
  const kev = kevKeysFor(kev_match, `${vendor}|${product}`.toLowerCase())
  return {
    id: slug(display), display, category, hint: `${vendor} ${product}`, vendor, product, kind, kev,
    aliases: aliases.split(',').map((s) => s.trim()).filter(Boolean), version_hint, kev_count: sumKev(kev), curated: true, order: i,
  }
})

// Guess the device type from the name when KEV does not say; if wrong, the user changes the type on the detail page.
const KIND_HINT: [RegExp, K][] = [
  [/firewall|fortios|pan-os|asa|sonicos|firebox|utm/i, 'firewall'], [/router|routeros|vigor|archer|wan vpn/i, 'router'], [/switch/i, 'switch'],
  [/access point|\bwap\b|wireless|wifi/i, 'ap'], [/nas\b|storage|diskstation|qts/i, 'nas'], [/camera|ipc|dvr|surveillance/i, 'camera'], [/nvr/i, 'nvr'],
  [/printer|mfp|laserjet/i, 'printer'], [/wordpress|joomla|drupal|cms|plugin|wiki|webmail|\bphp\b|struts|laravel|magento/i, 'web'],
  [/windows|macos|ios|chrome|firefox|office|reader|acrobat|winrar|7-zip|desktop|client/i, 'pc'], [/phone|mobile|android|\biot\b/i, 'iot'],
]
// An exploited-list name a curated product already covers (its kev keys) is that product: one entry, not a second one a person cannot
// tell apart ("Synology NAS (DSM)" and "Synology DiskStation Manager (DSM)"); the list's id still finds it (findById).
const coveredBy = new Map<string, CatalogEntry>()
for (const e of curated) for (const k of e.kev) if (!coveredBy.has(k)) coveredBy.set(k, e)
const folded = new Map<string, CatalogEntry>()
const autoById = new Map<string, CatalogEntry>()
for (const [i, r] of KEV.entries()) {
  const key = kevKey(r)
  const id = `kev:${slug(r.vendor)}:${slug(r.product)}`
  const owner = coveredBy.get(key)
  if (owner) { if (!folded.has(id)) folded.set(id, owner); continue }
  const dup = autoById.get(id)
  // Two KEV rows that differ only in an odd space (for example "Commerce and Magento") are the same product: one entry, keeping both match keys.
  if (dup) { dup.kev.push(key); dup.kev_count += r.kev_count; continue }
  const display = r.product.toLowerCase().startsWith(r.vendor.toLowerCase()) ? r.product : `${r.vendor} ${r.product}`
  const kind = KIND_HINT.find(([re]) => re.test(`${r.product} ${r.vendor}`))?.[1] ?? 'server'
  autoById.set(id, {
    id, display, category: OTHER, hint: `${r.vendor}, ${r.product}`, vendor: r.vendor, product: r.product, kind,
    kev: [key], aliases: [], version_hint: 'The version shown in the product, its About page or its admin console.', kev_count: r.kev_count, curated: false, order: 1000 + i,
  })
}
const auto = [...autoById.values()]

export const CATALOG: CatalogEntry[] = [...curated, ...auto]
export const findById = (id: string | undefined) => (id ? CATALOG.find((e) => e.id === id) ?? folded.get(id) : undefined)

const HAY = new Map(CATALOG.map((e) => [e.id, {
  name: fold(e.display), vendor: fold(e.vendor), product: fold(e.product), cat: fold(e.category), al: e.aliases.map(fold),
  all: fold(`${e.display} ${e.vendor} ${e.product} ${e.category} ${e.aliases.join(' ')}`),
}]))

const wordsOf = (s: string) => s.split(' ').filter(Boolean)

/** Ranking: exact name match > start of the name > first word in the name > alias/vendor > type; curated entries and entries with many exploited flaws come first. */
function score(e: CatalogEntry, terms: string[]): number {
  const h = HAY.get(e.id)!
  const nameWords = wordsOf(h.name)
  let total = 0
  let matched = 0
  const q = terms.join(' ')
  if (h.name === q) total += 200
  else if (h.name.startsWith(q)) total += 120
  for (const t of terms) {
    let s = 0
    if (nameWords.some((w) => w === t)) s = 40
    else if (nameWords.some((w) => w.startsWith(t))) s = 32
    else if (h.al.some((a) => a === t || wordsOf(a).includes(t))) s = 30
    else if (h.al.some((a) => a.startsWith(t) || wordsOf(a).some((w) => w.startsWith(t)))) s = 24
    else if (wordsOf(h.vendor).some((w) => w.startsWith(t))) s = 22
    else if (wordsOf(h.product).some((w) => w.startsWith(t))) s = 20
    else if (h.cat.includes(t)) s = 8
    else if (t.length >= 3 && h.all.includes(t)) s = 5
    if (s) matched++
    total += s
  }
  // A model number or version ("60f", "2019") need not match, as long as at least one word matches.
  const unmatched = terms.length - matched
  const unmatchedOnlyNumbers = terms.filter((t) => !HAY.get(e.id)!.all.includes(t)).every((t) => /\d/.test(t))
  if (unmatched > 0 && !(matched > 0 && unmatchedOnlyNumbers)) return 0
  if (matched === 0) return 0
  return total + (e.curated ? 15 - Math.min(e.order, 150) / 10 : 0) + Math.min(e.kev_count, 50) / 10
}

export interface SearchResult { items: CatalogEntry[]; total: number }

export function searchCatalog(q: string, limit = 30): SearchResult {
  const terms = wordsOf(fold(q))
  if (!terms.length) return { items: CATALOG.filter((e) => e.curated).slice(0, limit), total: CATALOG.length }
  const hits = CATALOG.map((e) => ({ e, s: score(e, terms) })).filter((x) => x.s > 0).sort((a, b) => b.s - a.s || a.e.order - b.e.order)
  return { items: hits.slice(0, limit).map((x) => x.e), total: hits.length }
}

/** Match EXACTLY the name in one CSV cell: id, display name, "vendor product" or alias. No fuzzy matching: "Dns" must not become D-Link. */
export function findCatalog(text: string): CatalogEntry | undefined {
  const n = fold(text)
  if (!n) return undefined
  const exact = CATALOG.find((e) => e.id === text.trim() || HAY.get(e.id)!.name === n || fold(`${e.vendor} ${e.product}`) === n)
  if (exact) return exact
  // Several products with the same alias/vendor name: take the first (the most common) only when they are the same vendor ("synology"); different vendors ("dns": D-Link, BIND) are not guessed.
  let hits = CATALOG.filter((e) => HAY.get(e.id)!.al.includes(n))
  if (!hits.length) hits = CATALOG.filter((e) => HAY.get(e.id)!.product === n)
  if (!hits.length) { const v = CATALOG.filter((e) => e.curated && HAY.get(e.id)!.vendor === n); if (v.length === 1) hits = v } // a bare vendor name: only when the vendor has one curated product
  return hits.every((e) => HAY.get(e.id)!.vendor === HAY.get(hits[0]!.id)!.vendor) ? hits[0] : undefined
}

/** A product the user typed (vendor + product): matches the exact pair in KEV if there is one, else the curated product of that name, else
 * its own key. Never every product of the vendor: a product nobody listed is not "exploited". */
export function customEntry(vendor: string, product: string): CatalogEntry {
  const v = fold(vendor)
  const p = fold(product)
  const exact = KEV.filter((r) => fold(r.vendor) === v && fold(r.product) === p).map(kevKey)
  const byName = findCatalog(product)
  const named = curated.find((e) => fold(e.vendor) === v && fold(e.product) === p) ?? (byName?.curated && fold(byName.vendor) === v ? byName : undefined)
  const kev = exact.length ? exact : named ? [...named.kev] : [`${vendor}|${product}`.toLowerCase()]
  return {
    id: '', display: `${vendor} ${product}`.trim(), category: OTHER, hint: `${vendor}, ${product}`, vendor, product, kind: 'unknown', kev, aliases: [],
    version_hint: '', kev_count: sumKev(kev), curated: false, order: 9999,
  }
}
export { sumKev }
